-- stg_mp_lab_results: part 1 of 9, 12000 rows. NOT APPLIED, branch only.
-- Licence on every row comes from the FILE, never the filename.
create table if not exists public.stg_mp_lab_results (
  col text,
  col_2 text,
  lab_lic_no text,
  lab_facility text,
  col_3 text,
  col_4 text,
  packaged_lic_no text,
  packaged_facility text,
  col_5 text,
  package text,
  source_harvest_names text,
  source_package_labels text,
  item text,
  col_6 text,
  category text,
  lab_testing text,
  test_date text,
  overall text,
  test_name text,
  passed text,
  result text,
  lte_date text,
  date text,
  notes text,
  source_file text not null,
  file_sha256 text not null,
  licence text not null,
  file_window text,
  ingested_at timestamptz not null default now()
);
alter table public.stg_mp_lab_results enable row level security;
drop policy if exists stg_mp_lab_results_read on public.stg_mp_lab_results;
create policy stg_mp_lab_results_read on public.stg_mp_lab_results for select to authenticated using (true);
